"""Build static/js/family-themes.js from NOBBIE's palette file.

Run from the repository root: python3 scripts/build_family_themes.py
Each palette becomes one colour theme whose numbers match the look's colour keys.
"""

import json
import math
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SOURCE = ROOT / "static" / "vendor" / "swatches" / "swatch_palettes.json"
TARGET = ROOT / "static" / "js" / "family-themes.js"
HEADER = (
    "// Generated by scripts/build_family_themes.py from static/vendor/swatches/swatch_palettes.json. Do not edit.\n"
)


def clamp(value: float, low: float, high: float) -> float:
    """Keep a number inside a range.

    Args:
        value: The number to limit.
        low: The smallest allowed value.
        high: The largest allowed value.

    Returns:
        The limited number.
    """
    return max(low, min(high, value))


def to_oklch(hex_colour: str) -> tuple[float, float, float]:
    """Convert a sRGB hex colour to OKLCH (Bjorn Ottosson's matrices).

    Args:
        hex_colour: A colour such as "#e63965".

    Returns:
        Lightness (0 to 1), chroma and hue in degrees (0 to 360).
    """
    rgb = [int(hex_colour.lstrip("#")[i : i + 2], 16) / 255 for i in (0, 2, 4)]
    r, g, b = [c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4 for c in rgb]
    ll = 0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b
    mm = 0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b
    ss = 0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b
    ll, mm, ss = ll ** (1 / 3), mm ** (1 / 3), ss ** (1 / 3)
    light = 0.2104542553 * ll + 0.7936177850 * mm - 0.0040720468 * ss
    a = 1.9779984951 * ll - 2.4285922050 * mm + 0.4505937099 * ss
    bb = 0.0259040371 * ll + 0.7827717662 * mm - 0.8086757660 * ss
    return light, math.hypot(a, bb), math.degrees(math.atan2(bb, a)) % 360


def theme_numbers(steps: dict[str, str]) -> dict[str, float]:
    """Map a palette's steps to the look's eight colour numbers.

    Args:
        steps: The palette steps keyed "50" to "700".

    Returns:
        The numbers nh, nc, ah, ac, wh, al, ad and pl, rounded and inside the look's ranges.
    """
    _, ac, ah = to_oklch(steps["500"])
    al = to_oklch(steps["600"])[0]
    ad = to_oklch(steps["300"])[0]
    pl, nc, nh = to_oklch(steps["50"])
    ah_i = round(ah) % 360
    near = min(abs(ah_i - 75), 360 - abs(ah_i - 75)) <= 40
    return {
        "nh": round(nh) % 360,
        "nc": round(clamp(nc, 0, 0.05), 3),
        "ah": ah_i,
        "ac": round(clamp(ac, 0, 0.22), 3),
        "wh": 25 if near else 75,
        "al": round(clamp(al, 0.14, 0.5), 3),
        "ad": round(clamp(ad, 0.72, 0.96), 3),
        "pl": round(clamp(pl, 0.88, 0.985), 3),
    }


def js(value: object) -> str:
    """Render a value as a JavaScript literal with single-quoted strings and bare keys.

    Args:
        value: A string, number, list or dict.

    Returns:
        The literal text.
    """
    if isinstance(value, str):
        return "'" + value.replace("\\", "\\\\").replace("'", "\\'") + "'"
    if isinstance(value, list):
        return "[" + ", ".join(js(v) for v in value) + "]"
    if isinstance(value, dict):
        return "{ " + ", ".join(f"{k}: {js(v)}" for k, v in value.items()) + " }"
    return json.dumps(value)


def main() -> None:
    """Write the generated module."""
    families = json.loads(SOURCE.read_text())
    hues: list[str] = []
    out = []
    for fam in families:
        if fam["hue"] not in hues:
            hues.append(fam["hue"])
        themes = [
            {
                "id": "fam:" + p["slug"],
                "name": p["name"],
                "swatch": p["steps"]["500"],
                "dark": p["steps"]["300"],
                "c": theme_numbers(p["steps"]),
            }
            for p in fam["palettes"]
        ]
        out.append({"slug": fam["slug"], "name": fam["name"], "hue": fam["hue"], "themes": themes})
    body = HEADER + "export const FAMILY_HUES = " + js(hues) + ";\n"
    body += "export const FAMILIES = [\n"
    for fam in out:
        head = {k: v for k, v in fam.items() if k != "themes"}
        body += "  { " + ", ".join(f"{k}: {js(v)}" for k, v in head.items()) + ", themes: [\n"
        body += "".join("    " + js(t) + ",\n" for t in fam["themes"])
        body += "  ] },\n"
    body += "];\n"
    TARGET.write_text(body)
    print(f"{len(out)} families, {sum(len(f['themes']) for f in out)} themes")


if __name__ == "__main__":
    main()
